          "code": "class MetricRegistry {\n    std::vector<Metric> data_;\n    mutable std::mutex mutex_;   // mutable — чтобы использовать в const-методах\npublic:\n    void add(Metric m) {\n        std::lock_guard<std::mutex> lock(mutex_);\n        data_.push_back(std::move(m));\n    }\n    std::size_t size() const {\n        std::lock_guard<std::mutex> lock(mutex_);   // и на чтение тоже!\n        return data_.size();\n    }\n};"
