          "code": "#include <array>\n#include <condition_variable>\n#include <cstddef>\n#include <mutex>\n#include <optional>\n\ntemplate<std::size_t Capacity>\nclass IntQueue {\n    static_assert(Capacity > 0);\n    std::array<int, Capacity> data_{};\n    std::size_t head_ = 0, tail_ = 0, size_ = 0;\n    bool closed_ = false;\n    std::mutex mutex_;\n    std::condition_variable not_empty_, not_full_;\npublic:\n    bool push(int value) {\n        std::unique_lock lock(mutex_);\n        not_full_.wait(lock, [&] { return closed_ || size_ < Capacity; });\n        if (closed_) return false;\n        data_[tail_] = value;\n        tail_ = tail_ + 1 == Capacity ? 0 : tail_ + 1;\n        ++size_;\n        lock.unlock();\n        not_empty_.notify_one();\n        return true;\n    }\n    std::optional<int> pop() {\n        std::unique_lock lock(mutex_);\n        not_empty_.wait(lock, [&] { return closed_ || size_ != 0; });\n        if (size_ == 0) return std::nullopt;\n        const int value = data_[head_];\n        head_ = head_ + 1 == Capacity ? 0 : head_ + 1;\n        --size_;\n        lock.unlock();\n        not_full_.notify_one();\n        return value;\n    }\n    void close() {\n        { std::lock_guard lock(mutex_); closed_ = true; }\n        not_empty_.notify_all();\n        not_full_.notify_all();\n    }\n};",
