          "type": "code",
          "code": "for (;;) {\n    std::deque<std::string> batch;\n    {\n        std::unique_lock lock(mutex);\n        ready.wait(lock, [&] { return closed || !queue.empty(); });\n        if (queue.empty()) return; // значит, closed == true\n        batch.swap(queue);\n    }\n    for (const auto& message : batch) {\n        try { sink.write(message); }\n        catch (...) { record_failure_noexcept(); }\n    }\n}",
