      "code": "#include <barrier>\n#include <exception>\n#include <mutex>\n#include <thread>\n#include <type_traits>\n#include <vector>\n\nint main() {\n    // Условие учебного примера: изменение snapshot не бросает из Metric.\n    static_assert(std::is_nothrow_copy_constructible_v<Metric> &&\n                  std::is_nothrow_move_constructible_v<Metric> &&\n                  std::is_nothrow_copy_assignable_v<Metric> &&\n                  std::is_nothrow_move_assignable_v<Metric> &&\n                  std::is_nothrow_destructible_v<Metric>);\n    std::vector<Metric> snapshot;\n    std::mutex snapshotMutex;\n\n    std::barrier syncPoint(3, [&]() noexcept {\n        std::lock_guard lock(snapshotMutex);\n        publishSnapshotNoThrow(snapshot);\n        snapshot.clear(); // Metric destructor обязан не выпускать исключение\n    });\n\n    auto collectorLoop = [&](const char* name) noexcept {\n        for (int cycle = 0; cycle < 10; ++cycle) {\n            try {\n                std::vector<Metric> metrics = collectFrom(name);\n                std::lock_guard lock(snapshotMutex);\n                snapshot.insert(snapshot.end(), metrics.begin(), metrics.end());\n            } catch (const std::exception& e) {\n                logNoThrow(name, e.what());\n                syncPoint.arrive_and_drop();\n                return;\n            } catch (...) {\n                logUnknownFailureNoThrow(name);\n                syncPoint.arrive_and_drop();\n                return;\n            }\n            syncPoint.arrive_and_wait();\n        }\n    };\n\n    std::vector<std::jthread> workers;\n    workers.reserve(3); // если это бросит, потоки ещё не запущены\n    const char* names[] = {\"memory\", \"cpu\", \"disk\"};\n    try {\n        for (const char* name : names)\n            workers.emplace_back(collectorLoop, name);\n    } catch (...) {\n        // Барьер уже учитывает всех троих. Убираем тех,\n        // кого не удалось запустить, ДО ожидания созданных потоков.\n        for (std::size_t missing = workers.size(); missing < 3; ++missing)\n            syncPoint.arrive_and_drop();\n        throw;\n    }\n    // workers уничтожается раньше syncPoint и snapshot:\n    // jthread дожидаются завершения созданных работников.\n}",
