      "solution": "#include <atomic>\n#include <optional>\n#include <string>\n\nstruct Snapshot {\n    int value;\n    std::string source;\n};\n\nSnapshot snapshot;                 // один writer, чтение после публикации\nstd::atomic<bool> ready{false};\n\nvoid publish() {\n    snapshot = Snapshot{42, \"cpu\"};\n    ready.store(true, std::memory_order_release);\n}\n\nstd::optional<Snapshot> try_read() {\n    if (!ready.load(std::memory_order_acquire))\n        return std::nullopt;\n    return snapshot;\n}\n\nstd::atomic<int> counter{0};\n\nbool add_if_below(int delta, int limit) {\n    // Контракт не допускает отрицательные значения; проверка ниже исключает переполнение.\n    if (delta < 0 || limit < 0 || delta > limit) return false;\n\n    int current = counter.load(std::memory_order_relaxed);\n    while (current <= limit - delta) {\n        if (counter.compare_exchange_weak(\n                current, current + delta,\n                std::memory_order_relaxed,\n                std::memory_order_relaxed)) {\n            return true;\n        }\n        // failure обновил current; weak мог отказать ложно\n    }\n    return false;\n}",
