      "solution": "class PeriodicCollector {\n    // Worker использует эти зависимости, поэтому они объявлены раньше.\n    std::mutex mutex_;\n    std::condition_variable_any changed_;\n    std::deque<Command> commands_;\n    bool accepting_ = true;\n    std::jthread worker_; // разрушается первым\n\n    void run(std::stop_token stop) noexcept {\n        try {\n            for (;;) {\n                std::unique_lock lock(mutex_);\n                changed_.wait(lock, stop, [this] {\n                    return !accepting_ || !commands_.empty();\n                });\n\n                if (!accepting_ || stop.stop_requested()) {\n                    commands_.clear(); // выбранная политика: cancel pending\n                    return;\n                }\n\n                Command command = std::move(commands_.front());\n                commands_.pop_front();\n                lock.unlock();\n\n                execute(command, stop);\n                // Контракт execute: регулярно наблюдать stop либо иметь\n                // документированную конечную верхнюю границу выполнения.\n            }\n        } catch (...) {\n            {\n                std::lock_guard lock(mutex_);\n                accepting_ = false;\n                commands_.clear();\n            }\n            changed_.notify_all();\n            record_worker_failure_noexcept();\n        }\n    }\n\npublic:\n    PeriodicCollector()\n        : worker_([this](std::stop_token st) { run(st); }) {}\n\n    void shutdown() noexcept {\n        {\n            std::lock_guard lock(mutex_);\n            accepting_ = false;\n        }\n        worker_.request_stop();\n        changed_.notify_all();\n        if (worker_.joinable()) worker_.join();\n    }\n\n    ~PeriodicCollector() { shutdown(); }\n};",
